import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    p = list(map(int, input_data[1:n+1]))
    s = input_data[n+1]

    current_bob_sum = 0
    diff = []

    for i in range(n):
        if s[i] == 'B':
            current_bob_sum += p[i]
            diff.append(-p[i])
        else:
            diff.append(p[i])

    max_gain = 0

    prefix_sum = 0
    for d in diff:
        prefix_sum += d
        if prefix_sum > max_gain:
            max_gain = prefix_sum

    suffix_sum = 0
    for d in reversed(diff):
        suffix_sum += d
        if suffix_sum > max_gain:
            max_gain = suffix_sum

    print(current_bob_sum + max_gain)

if __name__ == "__main__":
    solve()
